DO $p3c_do$
DECLARE
  v_data jsonb := $p3c_json${"standard":{"code":"DWA-A-102-2","title_de":"Grundsätze zur Bewirtschaftung und Behandlung von Regenwetterabflüssen zur Einleitung in Oberflächengewässer — Teil 2: Emissionsbezogene Bewertungen und Regelungen","title_en":"Principles for the management and treatment of stormwater runoff for discharge into surface waters — Part 2: Emission-related assessments and regulations","version":"Dezember 2020 (korrigierte Fassung: Stand August 2022)"},"worksheets":[{"code":"A1022-01","title_de":"Projektregistrierung","title_en":"Project Registration","phase":1,"archetype":"registration","order_index":10,"description":"Administrative project registration: client, project number, scope, regulatory framework."},{"code":"A1022-02","title_de":"Bilanzgebietsdefinition / Einzugsgebiet","title_en":"Balance Area Definition","phase":1,"archetype":"registration","order_index":20,"description":"Definition of the balance area (Bilanzgebiet), catchment boundaries, and connected area types."},{"code":"A1022-03","title_de":"Entwässerungssystem-Klassifikation","title_en":"Drainage System Classification","phase":1,"archetype":"registration","order_index":30,"description":"Classification of the drainage system: Trennsystem, Mischsystem, or modifizierte Systeme; determines calculation path."},{"code":"A1022-04","title_de":"Flächenkategorisierung nach Belastungskategorien I-III","title_en":"Surface Categorization by Pollution Category I-III","phase":2,"archetype":"data_collection","order_index":40,"description":"Categorization of impervious areas into Belastungskategorien I (low), II (moderate), III (heavily polluted) per Tabelle A.1."},{"code":"A1022-05","title_de":"Angeschlossene befestigte Fläche A_b,a","title_en":"Connected Impervious Area A_b,a","phase":2,"archetype":"data_collection","order_index":50,"description":"Determination of A_b,a (connected impervious area) and the area shares p_I, p_II, p_III; per-category breakdown."},{"code":"A1022-06","title_de":"Rechenwerte zu AFS63-Konzentrationen und Stoffabtrag (Tabelle 4)","title_en":"AFS63 Reference Values (Table 4)","phase":2,"archetype":"data_collection","order_index":60,"description":"Standard reference values for AFS63 concentrations (C_R,AFS63) and area-specific load (b_R,a,AFS63) per Belastungskategorie; allowable load b_R,e,zul,AFS63 = 280 kg/(ha·a)."},{"code":"A1022-07","title_de":"Hydrologische Eingangsdaten","title_en":"Hydrological Input Data","phase":2,"archetype":"data_collection","order_index":70,"description":"Hydrological inputs: critical rain intensity r_krit, annual precipitation h_Na, flow time t_f, mean topographic slope class NG_m."},{"code":"A1022-08","title_de":"Kanalnetz- und Kläranlagen-Eingangsdaten","title_en":"Sewer Network & WWTP Input Data","phase":2,"archetype":"data_collection","order_index":80,"description":"Network and WWTP inputs: combined-flow capacity Q_M, dry-weather Q_T,aM and Q_T,h,max, foreign water Q_F, CSB concentration C_T,aM,CSB, d·I product."},{"code":"A1022-09","title_de":"Abminderungswert f_D (Anhang C)","title_en":"Reduction Factor f_D (Annex C)","phase":2,"archetype":"data_collection","order_index":90,"description":"Reduction factor f_D for permeable surface coverings (green roofs, permeable pavers) per Annex C Table C.1."},{"code":"A1022-10","title_de":"Stoffabtrag-Bilanzierung AFS63","title_en":"AFS63 Pollutant Load Balance","phase":3,"archetype":"calculation","order_index":100,"description":"Calculation of per-area B_R,a,AFS63,i (Gl. 3), total B_R,a,AFS63 (Gl. 4), and area-specific b_R,a,AFS63 (Gl. 5)."},{"code":"A1022-11","title_de":"Erforderlicher Wirkungsgrad η_erf","title_en":"Required Treatment Efficiency η_erf","phase":3,"archetype":"calculation","order_index":110,"description":"Required treatment efficiency η_erf = Max(0; 1 - b_R,e,zul / b_R,a) · 100 (Gl. 6)."},{"code":"A1022-12","title_de":"Resultierender Stoffaustrag nach Behandlung","title_en":"Resulting Pollutant Load after Treatment","phase":3,"archetype":"calculation","order_index":120,"description":"Resulting pollutant emission after treatment: per-facility B_R,e,AFS63,i (Gl. 7) and overall B_R,e,AFS63 (Gl. 8)."},{"code":"A1022-13","title_de":"Kritischer Regenabfluss Q_R,krit","title_en":"Critical Rainwater Runoff Q_R,krit","phase":3,"archetype":"calculation","order_index":130,"description":"Critical rainwater runoff Q_R,krit = r_krit · A_b,a · f_D (Gl. B.1)."},{"code":"A1022-14","title_de":"Bemessungszufluss Q_Bem,Tr","title_en":"Design Inflow Q_Bem,Tr (Separate Sewer)","phase":3,"archetype":"calculation","order_index":140,"description":"Design inflow for the Regenklärbecken: Q_Bem,Tr = Q_R,krit + Q_F (Gl. B.2)."},{"code":"A1022-15","title_de":"Oberflächenbeschickung q_A,Bem","title_en":"Surface Loading Rate q_A,Bem","phase":3,"archetype":"calculation","order_index":150,"description":"Surface loading rate q_A,Bem = 3.6 · Q_Bem,Tr / A_sed (Gl. B.3); existing facilities q_A,b = q_A,max · 15 / r_krit (Gl. 9)."},{"code":"A1022-16","title_de":"Sedimentationswirkungsgrad η_sed","title_en":"Sedimentation Efficiency η_sed","phase":3,"archetype":"calculation","order_index":160,"description":"Sedimentation efficiency η_sed = f(q_A,max) via Tabelle B.1 lookup."},{"code":"A1022-17","title_de":"Gesamtwirkungsgrad η_ges","title_en":"Overall Efficiency η_ges","phase":3,"archetype":"calculation","order_index":170,"description":"Overall efficiency η_ges = f(q_A,Bem) read from Bild 4 / Zusatzdatei regression: q_A,Bem = -8.333 · ln(η_ges) - 1.6629."},{"code":"A1022-18","title_de":"Bemessung Regenklärbecken (A_RKB, V_RKB) und Schrägklärer (A_eff)","title_en":"Regenklärbecken Sizing (A_RKB, V_RKB) and Schrägklärer (A_eff)","phase":3,"archetype":"calculation","order_index":180,"description":"Sizing: A_RKB = 3.6 · Q_Bem,Tr / q_A,Bem (Gl. 10); V_RKB = A_RKB · h_RKB (Gl. 11); for Schrägklärer A_eff = 3.6 · Q_Bem,Tr / q_A,max (Gl. 12)."},{"code":"A1022-19","title_de":"Regenabfluss im Drosselabfluss Q_R,Dr","title_en":"Rainwater in Throttled Flow Q_R,Dr","phase":3,"archetype":"calculation","order_index":190,"description":"Rainwater portion of throttled flow Q_R,Dr = Q_M - Q_T,aM - Q_R,Tr (Gl. B.7); specific q_R,Dr = Q_R,Dr / A_b,a (Gl. B.8)."},{"code":"A1022-20","title_de":"TW-Abflussspende q_T,aM","title_en":"Dry Weather Flow Rate q_T,aM","phase":3,"archetype":"calculation","order_index":200,"description":"Specific dry-weather flow rate q_T,aM = Q_T,aM / A_b,a (Gl. B.9)."},{"code":"A1022-21","title_de":"Fließzeitabminderung a_f","title_en":"Flow Time Reduction Factor a_f","phase":3,"archetype":"calculation","order_index":210,"description":"Flow-time factor a_f (Gl. B.10): piecewise function of t_f, capped at 0.885."},{"code":"A1022-22","title_de":"Mittlerer Regenabfluss bei Entlastung Q_R,e","title_en":"Mean Rainwater Flow during Overflow Q_R,e","phase":3,"archetype":"calculation","order_index":220,"description":"Q_R,e from overflow data (Gl. B.11) or empirical Q_R,e = a_f · (3.0 · A_b,a · f_D + 3.2 · Q_R,Dr) (Gl. B.12)."},{"code":"A1022-23","title_de":"Mittleres Mischverhältnis m","title_en":"Mean Mixing Ratio m","phase":3,"archetype":"calculation","order_index":230,"description":"Mean mixing ratio m = (Q_R,e + Q_R,Tr) / Q_T,aM (Gl. B.13, identical to Gl. 24)."},{"code":"A1022-24","title_de":"Einflusswerte a_c,CSB, a_h, a_a","title_en":"Influence Values a_c,CSB, a_h, a_a","phase":3,"archetype":"calculation","order_index":240,"description":"Influence values for design concentration: a_c,CSB (Gl. B.15a/b), a_h (Gl. B.16), d·I (Gl. B.17, B.18), x_a (Gl. B.19), tau (Gl. B.20), a_a (Gl. B.21)."},{"code":"A1022-25","title_de":"Bemessungskonzentration C_b,CSB","title_en":"Design Concentration C_b,CSB","phase":3,"archetype":"calculation","order_index":250,"description":"Design CSB concentration C_b,CSB = 600 · (a_c,CSB + a_h + a_a) (Gl. B.14)."},{"code":"A1022-26","title_de":"Flächenspez. Stoffabtrag b_R,a,AFS63 und Einflusswert a_R,AFS63","title_en":"Area-Specific Load b_R,a,AFS63 and Influence a_R,AFS63","phase":3,"archetype":"calculation","order_index":260,"description":"Weighted area load b_R,a,AFS63 (Gl. B.22) and AFS63 influence value a_R,AFS63 (Gl. B.23a/b = Gl. 21a/b), capped at 1.20."},{"code":"A1022-27","title_de":"Mittlere Entlastungskonzentration C_e,CSB","title_en":"Mean Overflow Concentration C_e,CSB","phase":3,"archetype":"calculation","order_index":270,"description":"Mean overflow CSB concentration: simple form Gl. 19, AFS63-adjusted Gl. 20 / B.24."},{"code":"A1022-28","title_de":"Zulässige Entlastungsrate e_0","title_en":"Permissible Overflow Rate e_0","phase":3,"archetype":"calculation","order_index":280,"description":"Permissible overflow rate e_0 (Gl. 13, 17, 18) with allowable load B_R,e,zul,CSB (Gl. 16) and balance equations (Gl. 14, 15)."},{"code":"A1022-29","title_de":"Hilfsgrößen H1 und H2","title_en":"Auxiliary Values H1 and H2","phase":4,"archetype":"calculation","order_index":290,"description":"Auxiliary values H1 = (4000 + 25·q_R,Dr/f_D) / (0.551 + q_R,Dr/f_D) and H2 = (36.8 + 13.5·q_R,Dr/f_D) / (0.5 + q_R,Dr/f_D), per Tabelle 6."},{"code":"A1022-30","title_de":"Erforderliches Gesamtspeichervolumen V_s, V","title_en":"Required Total Storage Volume V_s, V","phase":4,"archetype":"calculation","order_index":300,"description":"Specific storage V_s = MAX(H1/(e_0+6) - H2 ; V_S,min); total V = V_s · A_b,a · f_D; with V_S,min = 5 m^3/ha."},{"code":"A1022-31","title_de":"Zusammenfassung Trennsystem-Ergebnisse","title_en":"Trennsystem Results Summary","phase":5,"archetype":"summary","order_index":310,"description":"Consolidation of all Trennsystem calculation outputs: AFS63 loads, treatment efficiencies, RKB dimensions."},{"code":"A1022-32","title_de":"Zusammenfassung Mischsystem-Ergebnisse","title_en":"Mischsystem Results Summary","phase":5,"archetype":"summary","order_index":320,"description":"Consolidation of all Mischsystem calculation outputs: e_0, H1/H2, V_s, V, m, design concentrations."},{"code":"A1022-33","title_de":"Gesamtübersicht — bauwerksbezogene Nachweise","title_en":"Combined Project Overview — Structure-Related Verifications","phase":5,"archetype":"summary","order_index":330,"description":"Project-level overview incorporating both streams; structure-related criteria per §7.3.4 (RÜB, SKO, SKU, RÜ) using Gl. 24-28."},{"code":"A1022-34","title_de":"Nachweis: Stoffabtrag AFS63 (Trennsystem)","title_en":"Verification: AFS63 Pollutant Load (Separate Sewer)","phase":6,"archetype":"verification","order_index":340,"description":"Pass/fail checks: b_R,e,AFS63 ≤ 280 kg/(ha·a) AND η_ges ≥ η_erf."},{"code":"A1022-35","title_de":"Nachweis: Gesamtspeichervolumen (Mischsystem)","title_en":"Verification: Total Storage Volume (Combined Sewer)","phase":6,"archetype":"verification","order_index":350,"description":"Pass/fail checks: V_s ≥ V_S,min = 5 m³/ha; V_s ≤ 40 m³/ha (economic upper limit per §7.3.3.1)."},{"code":"A1022-36","title_de":"Nachweis: Mindestmischverhältnis m","title_en":"Verification: Minimum Mixing Ratio m","phase":6,"archetype":"verification","order_index":360,"description":"Pass/fail check: m ≥ 7 for C_T,aM,CSB ≤ 600 mg/l (Gl. 22), else m ≥ (C_T,aM,CSB - 180) / 60 (Gl. 23)."}],"sections":[{"ws_code":"A1022-01","code":"A","title_de":"Purpose and Context","order_index":1,"parent_code":null},{"ws_code":"A1022-01","code":"B","title_de":"Input Parameters","order_index":2,"parent_code":null},{"ws_code":"A1022-01","code":"C","title_de":"Worksheet-Specific Content","order_index":3,"parent_code":null},{"ws_code":"A1022-01","code":"D","title_de":"Results / Derived Values","order_index":4,"parent_code":null},{"ws_code":"A1022-01","code":"F","title_de":"Results Summary","order_index":5,"parent_code":null},{"ws_code":"A1022-01","code":"J","title_de":"Output Transfer Table","order_index":6,"parent_code":null},{"ws_code":"A1022-01","code":"K","title_de":"Notes and Assumptions","order_index":7,"parent_code":null},{"ws_code":"A1022-01","code":"L","title_de":"Approval","order_index":8,"parent_code":null},{"ws_code"