se_reference":"§7.3.4.2","description":"Overall verdict for the m ≥ m_min check at each RÜB.","consumer_worksheets":["A1022-33"]},{"ws_code":"A1022-33","section_code":"F","symbol":"overall_verdict","label_de":"Gesamt-Verdikt","label_en":"Overall project verdict","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"enum:compliance_verdict"},"clause_reference":"—","description":"Aggregated project-level compliance verdict.","consumer_worksheets":["—"]}],"equations":[{"ws_code":"A1022-05","equation_number":"1","formula":"A_b_a = A_E_k_b - A_E_k_b_na","input_symbols":["A_E_k_b","A_E_k_b_na"],"output_symbol":"A_b_a","clause_reference":"Section 4.2.5","description":"Angeschlossene befestigte Flaeche A_b,a (nach Flaechenabkopplung)"},{"ws_code":"A1022-05","equation_number":"2","formula":"V_R_aM = h_Na * A_b_a * psi_aM * 10","input_symbols":["h_Na","A_b_a","psi_aM"],"output_symbol":"V_R_aM","clause_reference":"Section 4.3.3","description":"Jahresregenwasserabflussvolumen V_R,aM"},{"ws_code":"A1022-10","equation_number":"3","formula":"B_R_a_AFS63_i = A_b_a_i * b_R_a_AFS63_i","input_symbols":["A_b_a_i","b_R_a_AFS63_i"],"output_symbol":"B_R_a_AFS63_i","clause_reference":"Section 5.2.3.2","description":"Stoffabtrag AFS63, Teilflaeche i"},{"ws_code":"A1022-10","equation_number":"4","formula":"B_R_a_AFS63 = Sum(B_R_a_AFS63_i)","input_symbols":["B_R_a_AFS63_i (alle i)"],"output_symbol":"B_R_a_AFS63","clause_reference":"Section 5.2.3.2","description":"Gesamter Stoffabtrag AFS63 (Summe ueber Teilflaechen)"},{"ws_code":"A1022-10","equation_number":"5","formula":"b_R_a_AFS63 = B_R_a_AFS63 / A_b_a","input_symbols":["B_R_a_AFS63","A_b_a"],"output_symbol":"b_R_a_AFS63","clause_reference":"Section 5.2.3.2","description":"Flaechenspez. Stoffabtrag AFS63 b_R,a,AFS63"},{"ws_code":"A1022-11","equation_number":"6","formula":"eta_erf = Max(0; 1 - b_R_e_zul_AFS63 / b_R_a_AFS63)  (-)  | eta_erf = Max(0; 1 - b_R_e_zul_AFS63 / b_R_a_AFS63) * 100  in %","input_symbols":["b_R_e_zul_AFS63","b_R_a_AFS63"],"output_symbol":"eta_erf","clause_reference":"Section 5.2.3.2","description":"Erforderlicher Wirkungsgrad eta_erf (zwei Formen: fraktional und Prozent)"},{"ws_code":"A1022-12","equation_number":"7","formula":"B_R_e_AFS63_i = A_b_a_i * (1 - eta_i) * b_R_a_AFS63_i","input_symbols":["A_b_a_i","eta_i","b_R_a_AFS63_i"],"output_symbol":"B_R_e_AFS63_i","clause_reference":"Section 5.2.3.2","description":"Stoffaustrag pro Teilflaeche nach Behandlung (dezentral)"},{"ws_code":"A1022-12","equation_number":"8","formula":"B_R_e_AFS63 = (1 - eta_ges) * B_R_a_AFS63","input_symbols":["eta_ges","B_R_a_AFS63"],"output_symbol":"B_R_e_AFS63","clause_reference":"Section 5.2.3.2","description":"Stoffaustrag Gesamtgebiet bei zentraler Behandlung"},{"ws_code":"A1022-15","equation_number":"9","formula":"q_A_b = q_A_max * 15 / r_krit","input_symbols":["q_A_max","r_krit"],"output_symbol":"q_A_b","clause_reference":"Section 6.2.2","description":"Massgebende Oberflaechenbeschickung im Bestand q_A,b"},{"ws_code":"A1022-18","equation_number":"10","formula":"A_RKB = 3.6 * Q_Bem_Tr / q_A_Bem","input_symbols":["Q_Bem_Tr","q_A_Bem"],"output_symbol":"A_RKB","clause_reference":"Section 6.2.3","description":"Sedimentationswirksame Oberflaeche A_RKB"},{"ws_code":"A1022-18","equation_number":"11","formula":"V_RKB = A_RKB * h_RKB","input_symbols":["A_RKB","h_RKB"],"output_symbol":"V_RKB","clause_reference":"Section 6.2.4","description":"Erforderliches Speichervolumen V_RKB"},{"ws_code":"A1022-18","equation_number":"12","formula":"A_eff = 3.6 * Q_Bem_Tr / q_A_max","input_symbols":["Q_Bem_Tr","q_A_max"],"output_symbol":"A_eff","clause_reference":"Section 6.3","description":"Erforderliche Oberflaeche Sedimentationskoerper A_eff (Schraegklaerer)"},{"ws_code":"A1022-28","equation_number":"13","formula":"e_0 = V_e_MWUe / V_R_aM * 100","input_symbols":["V_e_MWUe","V_R_aM"],"output_symbol":"e_0","clause_reference":"Section 7.3.2.2","description":"Entlastungsrate e_0 (volumenbezogene Definition)"},{"ws_code":"A1022-28","equation_number":"14","formula":"B_R_e = (V_R_aM * e_0 * C_e + V_R_aM * (100 - e_0) * C_KA) / 100 <= B_R_e_zul","input_symbols":["V_R_aM","e_0","C_e","C_KA","B_R_e_zul"],"output_symbol":"B_R_e","clause_reference":"Section 7.3.2.2","description":"Resultierender Stoffaustrag B_R,e (Bilanzgleichung)"},{"ws_code":"A1022-28","equation_number":"15","formula":"e_0 <= (B_R_e_zul - V_R_aM * C_KA) / (V_R_aM * C_e - V_R_aM * C_KA) * 100","input_symbols":["B_R_e_zul","V_R_aM","C_KA","C_e"],"output_symbol":"e_0","clause_reference":"Section 7.3.2.2","description":"Bestimmungsgleichung zulaessige Entlastungsrate (allgemein, aus Bilanz)"},{"ws_code":"A1022-28","equation_number":"16","formula":"B_R_e_zul_CSB = V_R_aM * C_R_CSB","input_symbols":["V_R_aM","C_R_CSB"],"output_symbol":"B_R_e_zul_CSB","clause_reference":"Section 7.3.2.2","description":"Zulaessiger Stoffaustrag CSB B_R,e,zul,CSB"},{"ws_code":"A1022-28","equation_number":"17","formula":"e_0 <= (C_R_CSB - C_KA_CSB) / (C_e_CSB - C_KA_CSB) * 100","input_symbols":["C_R_CSB","C_KA_CSB","C_e_CSB"],"output_symbol":"e_0","clause_reference":"Section 7.3.2.2","description":"Zulaessige Entlastungsrate (CSB-Zielfunktion, allgemein)"},{"ws_code":"A1022-28","equation_number":"18","formula":"e_0 <= (107 - 70) / (C_e_CSB - 70) * 100 = 3700 / (C_e_CSB - 70)","input_symbols":["C_e_CSB"],"output_symbol":"e_0","clause_reference":"Section 7.3.2.2","description":"Zulaessige Entlastungsrate (CSB-Standardwerte: 107, 70 mg/l)"},{"ws_code":"A1022-27","equation_number":"19","formula":"C_e_CSB = (C_R_CSB * m + C_b_CSB) / (m + 1)","input_symbols":["C_R_CSB","m","C_b_CSB"],"output_symbol":"C_e_CSB","clause_reference":"Section 7.3.2.2","description":"Entlastungskonzentration C_e,CSB (allgemein, ohne AFS63-Anpassung)"},{"ws_code":"A1022-27","equation_number":"20","formula":"C_e_CSB = (C_R_CSB * a_R_AFS63 * m + C_b_CSB) / (m + 1)","input_symbols":["C_R_CSB","a_R_AFS63","m","C_b_CSB"],"output_symbol":"C_e_CSB","clause_reference":"Section 7.3.2.2","description":"Entlastungskonzentration C_e,CSB (mit AFS63-Anpassung)"},{"ws_code":"A1022-26","equation_number":"21a","formula":"a_R_AFS63 = 1.0  if b_R_a_AFS63 <= 478","input_symbols":["b_R_a_AFS63"],"output_symbol":"a_R_AFS63","clause_reference":"Section 7.3.2.2","description":"Einflusswert a_R,AFS63 (Fall b_R,a <= 478)"},{"ws_code":"A1022-26","equation_number":"21b","formula":"a_R_AFS63 = Min(b_R_a_AFS63 / 478; 1.20)  if b_R_a_AFS63 > 478","input_symbols":["b_R_a_AFS63"],"output_symbol":"a_R_AFS63","clause_reference":"Section 7.3.2.2","description":"Einflusswert a_R,AFS63 (Fall b_R,a > 478)"},{"ws_code":"A1022-36","equation_number":"22","formula":"m >= 7  if C_T_aM_CSB <= 600","input_symbols":["C_T_aM_CSB"],"output_symbol":"m","clause_reference":"Section 7.3.4.2","description":"Mindestmischverhaeltnis m >= 7 (Standardfall)"},{"ws_code":"A1022-36","equation_number":"23","formula":"m >= (C_T_aM_CSB - 180) / 60  if C_T_aM_CSB > 600","input_symbols":["C_T_aM_CSB"],"output_symbol":"m","clause_reference":"Section 7.3.4.2","description":"Mindestmischverhaeltnis m (Starkverschmutzer C_T,aM,CSB > 600)"},{"ws_code":"A1022-33","equation_number":"24","formula":"m = (Q_R_e + Q_R_Tr) / Q_T_aM","input_symbols":["Q_R_e","Q_R_Tr","Q_T_aM"],"output_symbol":"m","clause_reference":"Section 7.3.4.2","description":"Bauwerksbezogenes mittleres Mischverhaeltnis m (aus Bauwerkskenngroessen)"},{"ws_code":"A1022-33","equation_number":"25a","formula":"r_krit = 15 * 120 / (t_f + 120)  if t_f <= 120","input_symbols":["t_f"],"output_symbol":"r_krit","clause_reference":"Section 7.3.4.5","description":"Kritische Regenspende r_krit (Fall t_f <= 120 min)"},{"ws_code":"A1022-33","equation_number":"25b","formula":"r_krit = 7.5  if t_f > 120","input_symbols":["t_f"],"output_symbol":"r_krit","clause_reference":"Section 7.3.4.5","description":"Kritische Regenspende r_krit (Fall t_f > 120 min)"},{"ws_code":"A1022-33","equation_number":"26","formula":"Q_Dr >= Q_T_aM + Q_R_krit + Sum(Q_Dr_i)","input_symbols":["Q_T_aM","Q_R_krit","Q_Dr_i"],"output_symbol":"Q_Dr","clause_reference":"Section 7.3.4.5","description":"Mindestdrosselabfluss Q_Dr (kritischer Mischwasserabfluss)"},{"ws_code":"A1022-33","equation_number":"27","formula":"m_Rue = (Q_Dr - Q_T_aM) / Q_T_aM","input_symbols":["Q_Dr","Q_T_aM"],"output_symbol":"m_Rue","clause_reference":"Section 7.3.4.5","description":"Mischverhaeltnis im kritischen Abfluss m_Rue"},{"ws_code":"A1022-33","equation_number":"28","formula":"Q_Dr >= (m_Rue + 1) * Q_T_aM","input_symbols":["m_Rue","Q_T_aM"],"output_symbol":"Q_Dr","clause_reference":"Section 7.3.4.5","description":"Drosselabfluss zur Einhaltung Mindestmischverhaeltnis"},{"ws_code":"A1022-13","equation_number":"B.1","formula":"Q_R_krit = r_krit * A_b_a * f_D","input_symbols":["r_krit","A_b_a","f_D"],"output_symbol":"Q_R_krit","clause_reference":"Section B.1.3","description":"Kritischer Regenabfluss Q_R,krit (mit f_D)"},{"ws_code":"A1022-14","equation_number":"B.2","formula":"Q_Bem_Tr = Q_R_krit + Q_F","input_symbols":["Q_R_krit","Q_F"],"output_symbol":"Q_Bem_Tr","clause_reference":"Section B.2.1","description":"Bemessungszufluss Q_Bem,Tr"},{"ws_code":"A1022-15","equation_number":"B.3","formula":"q_A_Bem = 3.6 * Q_Bem_Tr / A_sed","input_symbols":["Q_Bem_Tr","A_sed"],"output_symbol":"q_A_Bem","clause_reference":"Section B.2.2","description":"Oberflaechenbeschickung q_A,Bem (Trennsystem)"},{"ws_code":"A1022-08","equation_number":"B.4","formula":"Q_M = f_S_QM * Q_S_aM + Q_F","input_symbols":["f_S_QM","Q_S_aM","Q_F"],"output_symbol":"Q_M","clause_reference":"Section B.3.2.3.1","description":"Mischwasserabfluss Q_M (aus Schmutzwasser + Fremdwasser)"},{"ws_code":"A1022-08","equation_number":"B.5","formula":"Sum(Q_M_i) <= Q_M","input_symbols":["Q_M_i","Q_M"],"output_symbol":"Q_M","clause_reference":"Section B.3.2.3.3","description":"Bedingung: Summe Q_M,i <= Q_M (parallele Teileinzugsgebiete)"},{"ws_code":"A1022-08","equation_number":"B.6","formula":"Q_R_Tr = Q_S_h_max_Tr","input_symbols":["Q_S_h_max_Tr"],"output_symbol":"Q_R_Tr","clause_reference":"Section B.3.2.4","description":"Regenabfluss aus Trenngebieten Q_R,Tr"},{"ws_code":"A1022-19","equation_number":"B.7","formula":"Q_R_Dr = Q_M - Q_T_aM - Q_R_Tr","input_symbols":["Q_M","Q_T_aM","Q_R_Tr"],"output_symbol":"Q_R_Dr","clause_reference":"Section B.3.3.1","description":"Regenanteil im Drosselabfluss Q_R,Dr"},{"ws_code":"A1022-19","equation_number":"B.8","formula":"q_R_Dr = Q_R_Dr / A_b_a","input_symbols":["Q_R_Dr","A_b_a"],"output_symbol":"q_R_Dr","clause_reference":"Section B.3.3.2","description":"Regenabflussspende q_R,Dr"},{"ws_code":"A1022-20","equation_number":"B.9","formula":"q_T_aM = Q_T_aM / A_b_a","input_symbols":["Q_T_aM","A_b_a"],"output_symbol":"q_T_aM","clause_reference":"Section B.3.3.3","description":"TW-Abflussspende q_T,aM"},{"ws_code":"A1022-21","equation_number":"B.10","formula":"a_f = 0.50 + 50 / (t_f + 100)  if t_f <= 30  |  a_f = 0.885  if t_f > 30","input_symbols":["t_f"],"output_symbol":"a_f","clause_reference":"Section B.3.3.4","description":"Fliesszeitabminderung a_f (stueckweise Funktion von t_f)"},{"ws_code":"A1022-22","equation_number":"B.11","formula":"Q_R_e = V_e_MWUe / (D_e * 3.6) + Q_R_Dr","input_symbols":["V_e_MWUe","D_e","Q_R_Dr"],"output_symbol":"Q_R_e","clause_reference":"Section B.3.3.5","description":"Mittlerer Regenabfluss bei Entlastung Q_R,e (aus Ueberlaufvolumen, allgemein)"},{"ws_code":"A1022-22","equation_number":"B.12","formula":"Q_R_e = a_f * (3.0 * A_b_a * f_D + 3.2 * Q_R_Dr)","input_symbols":["a_f","A_b_a","f_D","Q_R_Dr"],"output_symbol":"Q_R_e","clause_reference":"Section B.3.3.5","description":"Mittlerer Regenabfluss bei Entlastung Q_R,e (empirisch, fuer q_R,Dr < 2)"},{"ws_code":"A1022-23","equation_number":"B.13","formula":"m = (Q_R_e + Q_R_Tr) / Q_T_aM","input_symbols":["Q_R_e","Q_R_Tr","Q_T_aM"],"output_symbol":"m","clause_reference":"Section B.3.3.6","description":"Mittleres Mischverhaeltnis m"},{"ws_code":"A1022-25","equation_number":"B.14","formula":"C_b_CSB = 600 * (a_c_CSB + a_h + a_a)","input_symbols":["a_c_CSB","a_h","a_a"],"output_symbol":"C_b_CSB","clause_reference":"Section B.3.3.7","description":"Bemessungskonzentration CSB C_b,CSB"},{"ws_code":"A1022-24","equation_number":"B.15a","formula":"a_c_CSB = 1  if C_T_aM_CSB <= 600","input_symbols":["C_T_aM_CSB"],"output_symbol":"a_c_CSB","clause_reference":"Section B.3.3.8","description":"Einflusswert a_c,CSB (Fall C_T,aM,CSB <= 600)"},{"ws_code":"A1022-24","equation_number":"B.15b","formula":"a_c_CSB = C_T_aM_CSB / 600  if C_T_aM_CSB > 600","input_symbols":["C_T_aM_CSB"],"output_symbol":"a_c_CSB","clause_reference":"Section B.3.3.8","description":"Einflusswert a_c,CSB (Fall C_T,aM,CSB > 600)"},{"ws_code":"A1022-24","equation_number":"B.16","formula":"a_h = h_Na/800 - 1  if 600 <= h_Na <= 1000  |  a_h = -0.25  if h_Na < 600  |  a_h = +0.25  if h_Na > 1000","input_symbols":["h_Na"],"output_symbol":"a_h","clause_reference":"Section B.3.3.9","description":"Einflusswert Jahresniederschlag a_h (dreiteilig)"},{"ws_code":"A1022-24","equation_number":"B.17","formula":"d_I = Sum(d_i * I_S_i * l_i) / Sum(l_i)","input_symbols":["d_i","I_S_i","l_i"],"output_symbol":"d_I","clause_reference":"Section B.3.3.10","description":"Laengengewichtetes d*I aus Kanaldaten"},{"ws_code":"A1022-24","equation_number":"B.18","formula":"d_I = 0.001 * (1 + 2 * (NG_m - 1))","input_symbols":["NG_m"],"output_symbol":"d_I","clause_reference":"Section B.3.3.10","description":"d*I aus mittlerer Gelaendeneigungsklasse NG_m"},{"ws_code":"A1022-24","equation_number":"B.19","formula":"x_a = 24 * Q_T_aM / Q_T_h_max","input_symbols":["Q_T_aM","Q_T_h_max"],"output_symbol":"x_a","clause_reference":"Section B.3.3.10","description":"Kanalablagerungsfaktor x_a"},{"ws_code":"A1022-24","equation_number":"B.20","formula":"tau = 430 * (q_T_aM / f_D)^0.45 * (d_I)","input_symbols":["q_T_aM","f_D","d_I"],"output_symbol":"tau","clause_reference":"Section B.3.3.10","description":"Kanalablagerungsfaktor tau"},{"ws_code":"A1022-24","equation_number":"B.21","formula":"a_a = (24 / x_a)^2 * (2 - tau) / 10 ;  a_a >= 0","input_symbols":["x_a","tau"],"output_symbol":"a_a","clause_reference":"Section B.3.3.10","description":"Einflusswert Kanalablagerungen a_a (mit Floor a_a >= 0)"},{"ws_code":"A1022-26","equation_number":"B.22","formula":"b_R_a_AFS63 = (p_I * 280 + p_II * 530 + p_III * 760) / 100","input_symbols":["p_I","p_II","p_III"],"output_symbol":"b_R_a_AFS63","clause_reference":"Section B.3.3.11","description":"Flaechenspez. Stoffabtrag b_R,a,AFS63 (gewichteter Mittelwert)"},{"ws_code":"A1022-26","equation_number":"B.23a","formula":"a_R_AFS63 = 1.0  if b_R_a_AFS63 <= 478","input_symbols":["b_R_a_AFS63"],"output_symbol":"a_R_AFS63","clause_reference":"Section B.3.3.12","description":"Einflusswert a_R,AFS63 (Fall b_R,a <= 478) — identisch Gl. 21a"},{"ws_code":"A1022-26","equation_number":"B.23b","formula":"a_R_AFS63 = Min(b_R_a_AFS63 / 478; 1.20)  if b_R_a_AFS63 > 478","input_symbols":["b_R_a_AFS63"],"output_symbol":"a_R_AFS63","clause_reference":"Section B.3.3.12","description":"Einflusswert a_R,AFS63 (Fall b_R,a > 478) — identisch Gl. 21b"},{"ws_code":"A1022-27","equation_number":"B.24","formula":"C_e_CSB = (C_R_CSB * a_R_AFS63 * m + C_b_CSB) / (m + 1)","input_symbols":["C_R_CSB","a_R_AFS63","m","C_b_CSB"],"output_symbol":"C_e_CSB","clause_reference":"Section B.3.3.13","description":"Mittlere Entlastungskonzentration C_e,CSB (mit AFS63-Anpassung) — identisch Gl. 20"},{"ws_code":"A1022-29","equation_number":"T6.H1","formula":"H1 = (4000 + 25 * q_R_Dr / f_D) / (0.551 + q_R_Dr / f_D)","input_symbols":["q_R_Dr","f_D"],"output_symbol":"H1","clause_reference":"Tabelle 6","description":"Hilfsgroesse H1 (Tabelle 6, Zeile 37)"},{"ws_code":"A1022-29","equation_number":"T6.H2","formula":"H2 = (36.8 + 13.5 * q_R_Dr / f_D) / (0.5 + q_R_Dr / f_D)","input_symbols":["q_R_Dr","f_D"],"output_symbol":"H2","clause_reference":"Tabelle 6","description":"Hilfsgroesse H2 (Tabelle 6, Zeile 38)"},{"ws_code":"A1022-30","equation_number":"T6.Vs","formula":"V_s = Max(H1 / (e_0 + 6) - H2; V_S_min)","input_symbols":["H1","e_0","H2","V_S_min"],"output_symbol":"V_s","clause_reference":"Tabelle 6","description":"Spezifisches Speichervolumen V_s (Tabelle 6, Zeile 40)"},{"ws_code":"A1022-30","equation_number":"T6.V","formula":"V = V_s * A_b_a * f_D","input_symbols":["V_s","A_b_a","f_D"],"output_symbol":"V","clause_reference":"Tabelle 6","description":"Gesamtspeichervolumen V (Tabelle 6, Zeile 41)"},{"ws_code":"A1022-21","equation_number":"T6.a_f","formula":"a_f = Max(0.5 + 50 / (t_f + 100); 0.885)","input_symbols":["t_f"],"output_symbol":"a_f","clause_reference":"Tabelle 6","description":"Fliesszeitabminderung a_f (Tabelle 6, Zeile 23 — alternative Maximum-Form)"},{"ws_code":"A1022-17","equation_number":"REG-Bild4","formula":"q_A_Bem = -8.333 * ln(eta_ges) - 1.6629","input_symbols":["eta_ges"],"output_symbol":"q_A_Bem","clause_reference":"Bild 4 / Zusatzdatei RKB","description":"Regression q_A,Bem aus Bild 4 (Zusatzdatei RKB)"}],"compliance":[{"ws_code":"A1022-01","code":"REQ-01","title_de":"Anwendungsbereich Emissionsbezogen","condition":"assessment_scope contains 'emission_afs63'","description":"Project scope must declare emission-based assessment per DWA-A 102-2 §1.","clause_reference":"§1"},{"ws_code":"A1022-01","code":"REQ-02","title_de":"Systemtyp deklariert","condition":"system_type in [trenn, misch, modified, both]","description":"Drainage system type must be classified as Trennsystem, Mischsystem, modifiziertes System, or both.","clause_reference":"§1, §4.1"},{"ws_code":"A1022-01","code":"REQ-03","title_de":"Bilanzgebiet definiert","condition":"balance_area_size > 0","description":"Balance area (Bilanzgebiet) size and boundaries must be defined.","clause_reference":"§4.1, §4.2"},{"ws_code":"A1022-04","code":"REQ-04","title_de":"Flächenkategorisierung nach Tabelle A.1","condition":"A_b_a_I + A_b_a_II + A_b_a_III == A_b_a (within tolerance)","description":"All connected impervious sub-areas categorized into Belastungskategorien I, II, III per Anhang A Tabelle A.1.","clause_reference":"§5.2.1, Anh. A"},{"ws_code":"A1022-04","code":"REQ-05","title_de":"AFS63-Rechenwerte nach Tabelle 4","condition":"values match Tabelle 4 entries (subject to Pass 3b lookup)","description":"Standard AFS63 reference values for each Belastungskategorie applied (Tabelle 4).","clause_reference":"§5.2.2.3, Tabelle 4"},{"ws_code":"A1022-04","code":"REQ-06","title_de":"Hydrologische Eingangsdaten vorhanden","condition":"all values > 0","description":"Critical rain intensity r_krit, annual precipitation h_Na, longest flow time t_f provided.","clause_reference":"§4.3, Anh. B.1.2"},{"ws_code":"A1022-04","code":"REQ-07","title_de":"Netz- und KA-Daten vorhanden (Mischsystem)","condition":"if misch_active==true then all required > 0","description":"If Mischsystem: combined flow Q_M, dry-weather Q_T,aM, Q_T,h,max, CSB concentration C_T,aM,CSB provided.","clause_reference":"Anh. B.3.1, B.3.2"},{"ws_code":"A1022-04","code":"REQ-08","title_de":"Abminderungswert f_D erfasst","condition":"0 < f_D <= 1","description":"f_D applied for permeable surface coverings (Anhang C Tabelle C.1).","clause_reference":"Anh. C, Anh. B.3.2.2"},{"ws_code":"A1022-10","code":"REQ-09","title_de":"AFS63-Bilanz berechnet (Trenn)","condition":"b_R_a_AFS63 = computed via Gl. 5","description":"AFS63 specific load b_R,a,AFS63 calculated per Gl. 5 / B.22.","clause_reference":"§5.2.3.2"},{"ws_code":"A1022-10","code":"REQ-10","title_de":"Erforderlicher Wirkungsgrad berechnet","condition":"eta_erf computed; cap at >=0","description":"η_erf calculated per Gl. 6, comparing b_R,a to b_R,e,zul = 280.","clause_reference":"§5.2.3.2"},{"ws_code":"A1022-10","code":"REQ-11","title_de":"RKB-Bemessung durchgeführt","condition":"if trenn_active and treatment==RKB then A_RKB, V_RKB > 0","description":"RKB sized via Gl. 10, 11; A_RKB, V_RKB > 0; h_RKB ≥ 2 m.","clause_reference":"§6.2.3, §6.2.4"},{"ws_code":"A1022-10","code":"REQ-12","title_de":"Mittleres Mischverhältnis berechnet","condition":"m computed via Gl. B.13","description":"Mean mixing ratio m calculated per Gl. B.13 / 24.","clause_reference":"Anh. B.3.3.6"},{"ws_code":"A1022-10","code":"REQ-13","title_de":"Bemessungskonzentration C_b,CSB berechnet","condition":"C_b_CSB computed via Gl. B.14","description":"Design CSB concentration C_b,CSB calculated per Gl. B.14.","clause_reference":"Anh. B.3.3.7"},{"ws_code":"A1022-10","code":"REQ-14","title_de":"Zulässige Entlastungsrate e_0 berechnet","condition":"e_0 computed via Gl. 18","description":"Permissible overflow rate e_0 calculated per Gl. 18.","clause_reference":"§7.3.2.2"},{"ws_code":"A1022-10","code":"REQ-15","title_de":"AFS63-Einflusswert a_R berechnet und gekappt","condition":"1.0 <= a_R_AFS63 <= 1.20","description":"a_R,AFS63 computed per Gl. 21a/b = B.23a/b, capped at 1.20.","clause_reference":"§7.3.2.2, Anh. B.3.3.12"},{"ws_code":"A1022-29","code":"REQ-16","title_de":"Hilfsgrößen H1/H2 berechnet","condition":"H1, H2 > 0 computed via Tabelle 6","description":"Auxiliary values H1, H2 calculated per Tabelle 6 formulas.","clause_reference":"§7.3.2.3, Tabelle 6"},{"ws_code":"A1022-29","code":"REQ-17","title_de":"Gesamtspeichervolumen V berechnet","condition":"V_s >= V_S_min; V = V_s · A_b,a · f_D","description":"Specific V_s and total V calculated per Tabelle 6 with V_S,min = 5 m³/ha floor.","clause_reference":"§7.3.2.3, Tabelle 6"},{"ws_code":"A1022-29","code":"REQ-18","title_de":"Wirtschaftlichkeitsgrenze geprüft (V_s ≤ 40 m³/ha)","condition":"V_s <= 40 m³/ha OR alternative measures documented","description":"Economic upper limit on V_s: 40 m³/ha. If exceeded, investigate or apply Nachweisverfahren.","clause_reference":"§7.3.3.1"},{"ws_code":"A1022-31","code":"REQ-19","title_de":"Trennsystem-Ergebnisse konsolidiert","condition":"A1022-31 consolidation complete","description":"All Trennsystem outputs summarized in A1022-31.","clause_reference":"—"},{"ws_code":"A1022-31","code":"REQ-20","title_de":"Mischsystem-Ergebnisse konsolidiert","condition":"A1022-32 consolidation complete","description":"All Mischsystem outputs summarized in A1022-32.","clause_reference":"—"},{"ws_code":"A1022-31","code":"REQ-21","title_de":"Bauwerksbezogene Nachweise dokumentiert","condition":"if RÜB/SKO/SKU/RÜ exists then all structure criteria documented","description":"If §7.3.4 applicable: Q_Dr ≥ Q_T,aM + Q_R,krit + ΣQ_Dr,i; m_RÜ ≥ m; Entleerungsdauer constraints.","clause_reference":"§7.3.4"},{"ws_code":"A1022-34","code":"REQ-22","title_de":"Nachweis AFS63-Stoffaustrag (Trenn)","condition":"b_R_e_AFS63 ≤ 280 AND eta_ges >= eta_erf","description":"b_R,e,AFS63 ≤ 280 kg/(ha·a) AND eta_ges ≥ eta_erf.","clause_reference":"§5.2.3.2, §5.2.2.4"},{"ws_code":"A1022-34","code":"REQ-23","title_de":"Nachweis Mindestspeichervolumen (Misch)","condition":"V_s >= 5","description":"V_s ≥ V_S,min = 5 m³/ha.","clause_reference":"§7.3.2.3"},{"ws_code":"A1022-34","code":"REQ-24","title_de":"Nachweis Mindestmischverhältnis m","condition":"m >= m_min (branch by C_T,aM,CSB)","description":"For every RÜB: m ≥ 7 (if C_T,aM,CSB ≤ 600) or m ≥ (C_T,aM,CSB − 180) / 60 (if > 600).","clause_reference":"§7.3.4.2"},{"ws_code":"A1022-34","code":"REQ-25","title_de":"Entleerungsdauer 10–15 h (RÜB)","condition":"(V_s · 10000 / q_R_Dr / 3600) <= 15  (units: m³/ha → s → h)","description":"V_s / q_R,Dr ≤ 10–15 h for Regenüberlaufbecken; ≤ 15 h for Stauraumkanäle.","clause_reference":"§7.3.4.2, §7.3.4.4"},{"ws_code":"A1022-34","code":"REQ-26","title_de":"Behördenabstimmung (§5.2.4 messtechnischer Nachweis)","condition":"if mess_proof then authority_coordination_documented","description":"If measurement-based proof per §5.2.4: requires authority coordination and documentation.","clause_reference":"§5.2.4"},{"ws_code":"A1022-34","code":"REQ-27","title_de":"Nachweisverfahren bei q_R,Dr > 2 l/(s·ha)","condition":"if q_R_Dr > 2 then Nachweisverfahren_triggered","description":"If q_R,Dr > 2 l/(s·ha): Tabelle 6 application range exceeded — apply Nachweisverfahren per §8 with Q_M adjusted to q_R,Dr = 2.","clause_reference":"§7.3.3.1, §8.4"},{"ws_code":"A1022-01","code":"REQ-28","title_de":"Korrigierte Fassung Aug 2022 angewandt","condition":"regulation_edition == 'Dez 2020, korr. Aug 2022'","description":"All corrections per Korrekturen Stand August 2022 applied (B.1 with f_D, Tabelle B.1, equation renumbering, etc.).","clause_reference":"Korrekturen 2022"},{"ws_code":"A1022-04","code":"REQ-29","title_de":"Sonderflächen Kat. B/S nach §5.2.3.3 behandelt","condition":"if B/S surfaces present then §5.2.3.3 handling documented","description":"Surfaces with predominantly dissolved pollution (B-, S-types) treated separately per §5.2.3.3.","clause_reference":"§5.2.3.3"},{"ws_code":"A1022-10","code":"REQ-30","title_de":"Zusatzdateien für Berechnung herangezogen","condition":"Zusatzdatei use documented if applicable","description":"Excel companion files (Ermittlung Gesamtspeichervolumen, Bemessung Regenklärbecken) consulted where applicable.","clause_reference":"Zusatzdatei"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
